/**
 * Copies docs/candidate-guide.md, employer-guide.md and recruiter-guide.md
 * into src/modules/help-assistant/help-guides.generated.ts.
 *
 * The API image is built from apps/api alone (see Dockerfile), so it can't
 * read ../../docs at runtime. Run this after editing any guide:
 *
 *   npm run help:sync
 *
 * help-guides.spec.ts fails when the generated file and docs/ disagree, so a
 * guide edit can't silently leave the assistant answering from the old text.
 */
import fs from 'fs';
import path from 'path';
import { parseHelpGuide } from '../src/modules/help-assistant/help-guide-parse';

const DOCS = path.join(__dirname, '..', '..', '..', 'docs');
const OUT = path.join(__dirname, '..', 'src', 'modules', 'help-assistant', 'help-guides.generated.ts');

const guides = {
  candidate: parseHelpGuide(fs.readFileSync(path.join(DOCS, 'candidate-guide.md'), 'utf8')),
  employer: parseHelpGuide(fs.readFileSync(path.join(DOCS, 'employer-guide.md'), 'utf8')),
  recruiter: parseHelpGuide(fs.readFileSync(path.join(DOCS, 'recruiter-guide.md'), 'utf8')),
};

const body =
  '// GENERATED by scripts/sync-help-guides.ts from docs/*-guide.md. Do not edit by hand:\n' +
  '// edit the guide, then run `npm run help:sync`.\n' +
  "import type { HelpGuide } from './help-guide-parse';\n\n" +
  `export const HELP_GUIDES: Record<'candidate' | 'employer' | 'recruiter', HelpGuide> = ${JSON.stringify(guides, null, 2)};\n`;

fs.writeFileSync(OUT, body);
for (const [name, g] of Object.entries(guides)) {
  console.log(`${name}: ${g.sections.length} sections, ${g.markdown.length} chars`);
}
